QString ServiceDataWidget::projectComment()const{return comment_->text();}
void ServiceDataWidget::setProjectComment(const QString &text){comment_->setText(text);commentEdited_=edited_=true;}
void ServiceDataWidget::showPage(int index){tabs_->setCurrentIndex(qBound(0,index,2));if(!busy()&&!edited_)read();}
void ServiceDataWidget::read(){if(busy()||(canStart&&!canStart()))return;base_=snapshot?snapshot():ToolSnapshot{};if(!base_.valid()||!(quint8(base_.identity[19])&32)){state_->setText(tr("This ECU needs service-data firmware support and a complete configuration read."));return;}phase_=1;offset_=0;waiting_=false;data_.clear();writeOp_=0;deadline_=clock_.elapsed()+5000;if(busyChanged)busyChanged(true);display();pump();}
void ServiceDataWidget::startWrite(int op){if(busy()||(canStart&&!canStart())||!ServiceDataCodec::valid(data_)||unknown_)return;const auto current=snapshot?snapshot():ToolSnapshot{};if(!current.valid()||current.identity!=base_.identity||current.generation!=base_.generation){state_->setText(tr("ECU/base changed. Read the data again before saving; edits were retained."));return;}
    QByteArray args(5,0);args[0]=char(op);ServiceDataCodec::put32(args,1,ServiceDataCodec::u32(data_,278));
    if(op==2){const auto value=vin_->text().trimmed().toUpper();if(!ServiceDataCodec::validVin(value)){state_->setText(tr("VIN must be empty or 17 uppercase letters/digits, excluding I, O and Q."));return;}args+=char(value.size());args+=value.toLatin1();expected_=value;}
    if(op==3){const auto value=comment_->text();if(!ServiceDataCodec::validComment(value)){state_->setText(tr("Comment must have at most 64 printable Unicode characters."));return;}const auto utf8=value.toUtf8();QByteArray length(2,0);SensorCalibrationCodec::put(length,0,utf8.size());args+=length+utf8;expected_=value;}
    if(op==4){if(QMessageBox::question(this,tr("Reset Logbook"),tr("Reset the retained statistics in the ECU? VIN, comment and maps will be preserved."),QMessageBox::Yes|QMessageBox::Cancel,QMessageBox::Cancel)!=QMessageBox::Yes)return;args+="RESET";}
    phase_=3;writeOp_=op;request_="TUNUINO:N";request_+=args;deadline_=clock_.elapsed()+18000;if(busyChanged)busyChanged(true);display();state_->setText(tr("Saving ECU service data. No automatic retries."));pump();
}
void ServiceDataWidget::pump(){if(!busy())return;const auto current=snapshot?snapshot():ToolSnapshot{};if(!current.valid()||current.identity!=base_.identity||current.generation!=base_.generation||clock_.elapsed()>deadline_){finish(tr("ECU changed, disconnected or timed out. A save must be verified by reading again."),phase_==3);return;}if(waiting_||!exchange)return;QByteArray q("TUNUINO:N");if(phase_==1)q.append(char(0));else if(phase_==2){QByteArray args(8,0);args[0]=1;ServiceDataCodec::put32(args,1,ServiceDataCodec::u32(header_,12));SensorCalibrationCodec::put(args,5,offset_);args[7]=char(qMin(128,512-offset_));q+=args;}else q=request_;waiting_=true;if(!exchange(q,[this](const QByteArray &b){waiting_=false;receive(b);}))waiting_=false;}
void ServiceDataWidget::receive(const QByteArray &b){if(!busy())return;
    if(phase_==3){if(b.size()!=5||b[0]!=0){const int code=b.isEmpty()?0:quint8(b[0]);finish(code==0x85?tr("ECU service revision changed. Read again; local edits were retained."):code==0x86?tr("Saving requires stopped engine, no recent trigger edges, valid power and disarmed outputs."):tr("Save was not confirmed. Read again; an uncertain flash state requires an ECU restart."),code!=0x85&&code!=0x86);return;}phase_=1;offset_=0;data_.clear();deadline_=clock_.elapsed()+5000;return;}
    if(b.size()<21||b[0]!=0||b[1]!=1||(quint8(b[2])&~3u)||b[3]||ServiceDataCodec::u32(b,8)!=base_.generation||SensorCalibrationCodec::u16(b,16)!=512){finish(tr("Invalid service-data response."),writeOp_!=0);return;}
    if(phase_==1){if(b.size()!=21||SensorCalibrationCodec::u16(b,18)||b[20]||!ServiceDataCodec::u32(b,12)){finish(tr("Invalid service snapshot header."));return;}header_=b;phase_=2;return;}
    const int count=qMin(128,512-offset_);if(b.left(18)!=header_.left(18)||b.size()!=21+count||SensorCalibrationCodec::u16(b,18)!=offset_||quint8(b[20])!=count){finish(tr("Service snapshot changed during reading."),writeOp_!=0);return;}data_+=b.mid(21);offset_+=count;
    if(offset_==512){if(!ServiceDataCodec::valid(data_)||ServiceDataCodec::u32(data_,278)!=ServiceDataCodec::u32(header_,4)){data_.clear();finish(tr("Invalid ECU service-data payload."),writeOp_!=0);return;}unknown_=quint8(header_[2])&2;
        if((writeOp_==2&&ServiceDataCodec::vin(data_)!=expected_)||(writeOp_==3&&ServiceDataCodec::comment(data_)!=expected_)){finish(tr("Readback differs from the requested value. Save is not confirmed."),true);return;}
        if(writeOp_==0||writeOp_==2||!vinEdited_)vin_->setText(ServiceDataCodec::vin(data_));
        if(writeOp_==0||writeOp_==3||!commentEdited_)comment_->setText(ServiceDataCodec::comment(data_));
        if(writeOp_==0){vinEdited_=commentEdited_=false;}else if(writeOp_==2)vinEdited_=false;else if(writeOp_==3)commentEdited_=false;
        edited_=vinEdited_||commentEdited_;finish(unknown_?tr("ECU flash state is uncertain. Restart and read again before further saves."):quint8(header_[2])&1?tr("ECU data read. There are newer Logbook observations not yet checkpointed."):tr("ECU data read and confirmed. VIN/comment are separate from calibration pages."));}
}
void ServiceDataWidget::finish(const QString &message,bool unknown){phase_=0;waiting_=false;if(unknown)unknown_=true;writeOp_=0;display();state_->setText(message);if(busyChanged)busyChanged(false);}
void ServiceDataWidget::display(){const bool valid=ServiceDataCodec::valid(data_);for(auto *button:{saveVin_,saveComment_,checkpoint_,reset_})button->setEnabled(valid&&!busy()&&!unknown_);export_->setEnabled(valid&&!busy()&&!unknown_);read_->setEnabled(!busy());vin_->setEnabled(!busy());comment_->setEnabled(!busy());if(!valid)return;
    const int mask=quint8(data_[294]);const QString missing=tr("Unavailable");const QStringList names{tr("Maximum RPM"),tr("Maximum MAP kPa"),tr("Maximum CLT °C"),tr("Maximum IAT °C"),tr("Full-throttle time s"),tr("Maximum trigger error count"),tr("Latched output faults"),tr("Checkpoint uptime s (saving session)"),tr("Maximum EGT"),tr("Maximum vehicle speed"),tr("Watchdog reset count"),tr("WBO circuit calibration")};
    const QStringList values{mask&1?QString::number(ServiceDataCodec::u32(data_,282)/1000.0,'f',0):missing,mask&2?QString::number(ServiceDataCodec::u32(data_,286)/1000.0,'f',2):missing,mask&4?QString::number(qint32(ServiceDataCodec::u32(data_,290))/1000.0,'f',2):missing,mask&8?QString::number(qint32(ServiceDataCodec::u32(data_,296))/100.0,'f',2):missing,QString::number(ServiceDataCodec::u64(data_,300)/1000.0,'f',2),QString::number(ServiceDataCodec::u32(data_,308)),QStringLiteral("0x%1").arg(ServiceDataCodec::u32(data_,312),2,16,QLatin1Char('0')),ServiceDataCodec::u64(data_,324)?QString::number(ServiceDataCodec::u64(data_,324)/1000.0,'f',2):missing,missing,missing,missing,missing};
    for(int i=0;i<names.size();++i){book_->setItem(i,0,new QTableWidgetItem(names[i]));book_->setItem(i,1,new QTableWidgetItem(values[i]));}
}
void ServiceDataWidget::exportProject(){if(saveMap){saveMap();return;}if(busy()||!snapshot)return;const auto current=snapshot();if(!current.valid()||current.identity!=base_.identity||current.generation!=base_.generation){state_->setText(tr("Read the current ECU configuration before exporting a project."));return;}const auto bytes=ServiceDataCodec::project(current,comment_->text());if(bytes.isEmpty())return;const auto path=QFileDialog::getSaveFileName(this,tr("Save project snapshot"),{},tr("Tunuino project (*.tnproj)"));if(path.isEmpty())return;QSaveFile file(path);if(!file.open(QIODevice::WriteOnly)||file.write(bytes)!=bytes.size()||!file.commit())QMessageBox::warning(this,tr("Project snapshot"),tr("Could not save the project."));}
void ServiceDataWidget::closeEvent(QCloseEvent *event){if(busy()){state_->setText(tr("Wait for the active ECU operation to finish."));event->ignore();return;}QWidget::closeEvent(event);}
